function ktNgayLui(iso, thang){ var p = iso.split('-'), d = new Date(+p[0], +p[1]-1-thang, +p[2]); return ngayISO(d); }
function ktNgayTru(iso, ngay){ var p = iso.split('-'), d = new Date(+p[0], +p[1]-1, +p[2]-ngay); return ngayISO(d); }
