    if(!mon.length) return;
    var h = {kh:k.kh, ten:k.ten, mon:mon, dn:k.dn, qh:k.qh, kn:k.kn, lt:k.lt, t105:k.t105, ly:[]};
    h.loai = k.qh>0 || k.kn>0;
