function ktPCNgayDai(x){ var m = String(x||'').match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/); return m ? 'ngày '+hai(+m[1])+' tháng '+hai(+m[2])+' năm '+m[3] : 'ngày …… tháng …… năm ……'; }
