  var t0 = ktKHDsTo()[0], ten = t0 ? ktFTen(t0, {kh:g.nam}) : 'Ke hoach KTGS '+g.nam+' - '+boDauTen(g.ten).slice(0, 60);   /* 3.140.2: Xã_Hội_KH năm */
