  if(cach==='word') return ktDocx(g.mau||'m01', g).then(function(bl){ giaoFile(bl, ten+'.docx'); bao('Đã tạo '+ten+'.docx — khuôn dự thảo HĐT cấp xã, chỉ lưu trên máy / Drive của anh.', 7); })
