function toCongSo(a, s){ ['tv','co','ra','moi','dn','qh','kn','t105','tn','tl'].forEach(function(f){ a[f] += s[f]; }); if(s.d105!==null) a.d105 += s.d105; if(s.soTo!==undefined) a.soTo += s.soTo; return a; }
